\label{Fortemente convexa - definição clássica} Let $U$ be a non-empty convex subset of $\mathbb{V}$ and $f: U \rightarrow \mathbb{R}$ be a function.
	\begin{enumerate}
		\item We say that $f$ is {\rm convex} if
		\begin{align*}
			f(ty+(1-t)z) \leq tf(y)+(1-t)f(z),
		\end{align*}
		for all $t \in [0,1]$ and any $y, z \in U.$
		\item We say that $f$ is {\rm strictly convex} if
		\begin{align*}
			f(ty+(1-t)z) < tf(y)+(1-t)f(z),
		\end{align*}
		for all $t \in (0,1)$ and any $y, z \in U$ with $y \neq z.$
		\item We say that $f$ is {\rm strongly} (or {\rm uniformly}) {\rm convex with modulus} $\gamma,$ if there is a constant $\gamma>0$ such that for any $y, z \in U$ and all $t \in [0,1],$ we have
		\begin{align*}
			f(ty+(1-t)z) \leq tf(y)+(1-t)f(z)-\frac{1}{2}\gamma t(1-t) \Vert y-z \Vert^2.
		\end{align*}
	\end{enumerate}

\label{Equivalencias - Fortemente convexa (Definicao Classica)} Let $U \subset \mathbb{V}$ be a non-empty open convex set and $f: U \rightarrow \mathbb{R}$ be a continuously differentiable function on $U$. Let $(y^1, \ldots, y^n)$ be a coordinate system of $\mathbb{V}$ relative to a basis of
	$\mathbb{V}.$ Then the following properties are equivalent:
	\begin{enumerate}
		\item The function $f$ is strongly convex in $U$ with modulus $\gamma > 0.$
		\item For any $y, z \in U$ 
		\begin{align*} f(z) \geq f(y) + d f_y(z-y) + \frac{1}{2}\gamma \Vert z-y\Vert^2.\end{align*}
		\item For any $y, z \in U$
		\begin{align*} (df_z - df_y) (z-y) \geq \gamma \Vert z-y\Vert^2. \end{align*}		
		\item \label{item_convexidade forte caso suave} When $f$ is twice continuously differentiable in $U$, the above properties are also equivalent to:

		The Hessian $\operatorname{Hess} f$ of $f$ is strongly (or uniformly) positive definite at every point of $U$. More precisely, 
		\begin{align*} (\operatorname{Hess} f)_y (v, v) := f_{y^iy^j}(y)v^i v^j \geq  \gamma \Vert v \Vert^2,  \forall y \in U, \forall v \in \mathbb{V}.\end{align*}
	\end{enumerate}

Consider $f: U \rightarrow \mathbb{R}$, where $U$ is a non-empty subset of $\mathbb{V}$.
	The {\rm epigraph} $\operatorname{epi} f$ of $f$ is a subset of $\mathbb{V} \times \mathbb{R}$ defined by
	\begin{align*}
		\operatorname{epi} f=\{(x,r)\in \mathbb{V} \times \mathbb{R}: \,\, f(x) \leq r,\,\, x\in U,\,\, r\in \mathbb{R}\}.
	\end{align*}

\label{Definicao de norma assimetrica} An {\rm asymmetric norm} on $\mathbb{V}$ is a function $F:\mathbb{V} \rightarrow [0,\infty)$ that satisfies the following conditions:
	\begin{enumerate}
		\item $F(y) = 0$ only if $y = 0;$
		\item $F(\mu y) = \mu F(y)$ for every $\mu \in [0, \infty)$ and $y \in \mathbb{V}$ (positive homogeneity);
		\item $F(y + z) \leq F(y) + F(z)$ for every $y, z \in \mathbb{V}$ (triangle inequality).
	\end{enumerate}

Let $F:\mathbb V \rightarrow [0,\infty)$ be an asymmetric norm.
	\begin{enumerate}
		\item The {\rm open ball} centered at $y$ and radius $r$ is the subset
		\begin{align*}
			B_F(y,r) = \{z \in \mathbb V : F(z-y) < r\}.
		\end{align*}
		\item The {\rm closed ball} centered at $y$ and radius $r$ is the subset
		\begin{align*}
			B_F[y,r] = \{z \in \mathbb V : F(z-y) \leq r\}.
		\end{align*}
		\item The {\rm sphere} centered at $y$ and radius $r$ is the subset
		\begin{align*}
			S_F[y,r] = \{z \in \mathbb V : F(z-y) = r\}.
		\end{align*}
	\end{enumerate}

\label{Fortemente convexa - definicao artigo R-H} Let $\check{F}$ be an asymmetric norm on $\mathbb{V}.$ We say that an asymmetric norm $F$ is {\rm strongly convex with respect to} $\check{F}$ if
	\begin{align*}
		F^2(z) \geq F^2(y) + \alpha(z-y) + \check{F}^2(z-y)
	\end{align*}
	for every $y,z \in \mathbb{V}$ and $\alpha \in \partial F^2(y),$ where $\partial F^2(y)$ is the {\rm subdifferential of $F^2$ at $y.$}

\label{norma de Minkowski}
	A function $F:\mathbb V \rightarrow [0, \infty)$ is a {\rm Minkowski norm} if 
	\begin{enumerate}
		\item $F$ is smooth in $\mathbb V\backslash\{0\}$;
		\item $F(\mu y) = \mu F(y)$ for every $\mu \in [0,\infty)$ and $y\in \mathbb V$;
		\item If $(y^1, \ldots, y^n)$ is a coordinate system of $\mathbb V$ with respect to a basis of $\mathbb V$, then the  $n\times n$ hessian matrix
		\begin{align*}
			\left( g_{ij(y)} \right) := \left( \left[\frac{1}{2} F^2 (y) \right]_{y^iy^j} \right), \hspace{5mm} i,j=1, \ldots, n,
		\end{align*}
		is positive definite for every $y \in \mathbb V\backslash \{0\}$, where the subscript $y^iy^j$ stands for the partial derivatives with respect to $y^i$ and $y^j$.
	\end{enumerate}

Every Minkowski norm is an asymmetric norm.
	\begin{proof}
		See Theorem 1.2.2 of \cite{BaoChernShen}.
	\end{proof}

\label{definition de mollifier}  

	\

	\begin{enumerate}

		\item Define $\eta \in \mathit{C}^{\infty}(\mathbb{R}^n)$ by
		\begin{align*}
			\eta(y) & :=  \begin{cases}
				C\exp\left(\frac{1}{ \|y\|^2-1}\right)  \quad & {\rm{if  \quad }}\|y\|<1  \\
				0   & {\rm{if}} \quad \|y\|\geq 1,
			\end{cases}
		\end{align*}
		where the constant $C> 0$ is chosen so that $\int_{\mathbb{R}^n}\eta \ dx=1.$

		\item  For  each $\varepsilon>0,$ define
		\begin{align}
			\label{epsilon-mollifier}
			\eta_{\varepsilon}(y) & :=  \frac{1}{\varepsilon^n}\eta\left(\frac{y}{\varepsilon}\right).
		\end{align}

		We call $\eta$ of {\rm standard mollifier.} For the sake of simplicity, we will also call $\eta_\varepsilon$ the standard mollifier.
	\end{enumerate}

If $f:U \rightarrow \mathbb{R}$ is a continuous function, its {\rm mollifier smoothing} $\eta_\varepsilon \ast f$ is the convolution of $\eta_\varepsilon$ and $f$ in $U_\varepsilon.$ That is,
	\begin{align*}
		(\eta_{\varepsilon}*f)(y)  := \int_U\eta_{\varepsilon}(y-z)f(z) \, dz = \int_{B_{\Vert \cdot \Vert}[0,\varepsilon]}\eta_\varepsilon(z)f(y-z) \, dz,
	\end{align*}
	for every $y \in U_\varepsilon.$

\label{propriedades da aplicacao mollifier} (Properties of mollifiers). Let $f:U\subset \mathbb{R}^n \rightarrow \mathbb{R}$ be a  continuous function, then the following statements are true:
	\begin{enumerate}
		\item \label{item_suavizacao suave}$(\eta_{\varepsilon}*f)\in \mathit{C}^{\infty}(U_\varepsilon)$.
		\item $(\eta_{\varepsilon}*f) \rightarrow f$ as $\varepsilon \rightarrow 0$ (pointwise).
		\item $(\eta_{\varepsilon}*f) \rightarrow f$ uniformly on compact subsets of $U.$
	\end{enumerate}

\label{derivada mollifier} 
	A consequence of the proof of Item \eqref{item_suavizacao suave} of Theorem \ref{propriedades da aplicacao mollifier} (see  \cite{Evans}) is:
	\begin{align*}
		D^\alpha(\eta_{\varepsilon}*f)(y) =  \int D^\alpha\eta_{\varepsilon}(y-z)f(z) \, dz = (D^\alpha\eta_{\varepsilon}*f)(y),
	\end{align*}
	for every $y \in U_\varepsilon$ and for every multi-index $\alpha=(\alpha_1,\ldots,\alpha_n)$.
	Moreover, when $f$ is $\mathit{C}^\infty,$ it follows that
	\begin{align*}
		D^\alpha(\eta_{\varepsilon}*f)(y) =  \int\eta_{\varepsilon}(z)D^\alpha f(y-z) \, dz =  (\eta_{\varepsilon}*D^\alpha f)(y).
	\end{align*}

\label{Definição ast_1 e ast_2}
	Let $k\in \{1, 2, \ldots, n-1\}$ and $\varepsilon >0$. 
	Decompose $\mathbb R^n$ as $\mathbb R^k \times \mathbb R^{n-k}$ and denote its variables by $x=(x^1, \ldots, x^k)$ and $y = (x^{k+1}, \ldots, x^n)$. 
	Let $U$ be an open subset of $\mathbb R^k$ and $V$ be an open subset of $\mathbb R^{n-k}$. 
	Consider a continuous function $f: U \times V \rightarrow \mathbb R$ and let $\eta_\varepsilon : B_{\Vert \cdot \Vert}(0,\varepsilon) \subset \mathbb R^k \rightarrow \mathbb R$ as in (\ref{epsilon-mollifier}). 
	The mollifier smoothing $(\eta_\varepsilon \ast_1 f): U_\varepsilon \times V \rightarrow \mathbb R$ of $f$ with respect to the first $k$ variables is defined as
	\begin{align*}
		(\eta_\varepsilon \ast_1 f) (x,y) = \int \eta_\varepsilon (z) f(x - z, y) \, dz.
	\end{align*}
	The mollifier smoothing $(\eta_\varepsilon \ast_2 f)$ with respect to the last $n-k$ variables is defined analogously.

\label{funcao convergencia uniforme}
	Let $U$ be an open subset of $\mathbb R^k$, $V$ be an open subset of $\mathbb R^{n-k}$ and $f: U \times V \rightarrow \mathbb R$ be a continuous function. Then $(\eta_\varepsilon \ast_1 f)$ converges uniformly to $f$ on compact subsets of $U \times V$. 
	The same result holds for $(\eta_\varepsilon \ast_2 f)$.

\label{definição de estrutura de Finlser} A {\rm Finsler structure of} $M$ is a function $F:TM \to [0, \infty)$ with the following properties:
	\begin{enumerate}
		\item $F$ is $C^\infty$ on the entire slit tangent bundle $TM\setminus 0 := \{(x, y) \in TM : x \in M, y \, \neq 0\};$
		\item For every $x \in M,$ $F(x, \cdot):T_xM \to [0, \infty)$ is a Minkowski norm.
	\end{enumerate}
	The pair $(M, F)$ is called a {\rm Finsler manifold}.

\label{define secao distinguida} 
	The {\rm distinguished section} $\ell$ is a section of $\pi^*TM$ defined by
	\begin{align}
		\ell \ = \ \ell_{(x,y)} \ := \ \frac{y^i}{F(x,y)} \, \frac{\partial}{\partial x^i}\Big\vert_x \ = \ \frac{y^i}{F}  \,  \frac{\partial}{\partial x^i} \ =: \ \ell^i  \,  \frac{\partial}{\partial x^i}.
		\label{define distinguished} 
	\end{align}

The {\rm fundamental tensor} is a section of inner products on $\otimes^2 \pi^\ast T^\ast  M$ given locally by
	\begin{align} \label{define tensor fundamental} 
		g_{ij(x,y)} = \frac{1}{2} \, \left( \frac{\partial^2 F^2}{\partial y^i \partial y^j}\right)(x,y).
	\end{align}

\label{define tensor de cartan} 
	Let $(M,F)$ be a Finsler manifold. 
	The {\rm Cartan tensor} is symmetric section $A$ on $\otimes^3 \pi^\ast T^\ast M$ defined locally by 
	\begin{align}
		\label{define componente tensor de cartan}
		A_{(x,y)} = A_{ijk(x,y)} dx^i \otimes dx^j \otimes dx^k
		:= \frac{F}{2} \, \frac{\partial g_{ij}}{\partial y^k} \, dx^i \otimes dx^j \otimes dx^k.
	\end{align}

\label{teorema conexao de Chern}
	Let $(M,F)$ be a Finsler manifold. The pulled-back bundle  $\pi^*TM$ admits a unique linear connection $\nabla$, called the {\rm  Chern connection}, such that its connection forms $\omega_j^{\ i}$, defined by
	\begin{align*}
		\nabla_X \, \frac{\partial}{\partial x^j} = \omega_j{}^i(X) \, \frac{\partial}{\partial x^i},
	\end{align*}
	are locally characterized by the following structural equations:
	\begin{itemize}
		\item {\bf Torsion freeness:}
		\begin{align*}
			d(dx^i)-dx^j\wedge \omega_j{}^i = - dx^j \wedge \omega_j{}^i=0.
		\end{align*}
		\item {\bf Almost $g$-compatibility:} 
		\begin{align*}
			dg_{ij}- g_{kj} \, \omega_i{}^k-g_{ik} \, \omega_j{}^k = 2 \, C_{ijs} \, \delta y^s.
		\end{align*}
	\end{itemize}

\label{Cartan Hasiguchi Berwarld} The connection forms of the following connections on $\pi^\ast TM$ are defined by:
	\begin{enumerate}
		\item {\rm Cartan connection}: $\omega_j{}^i + C^i{}_{jk} \, \delta y^k$.
		\item {\rm Hashiguchi connection}: $\omega_j{}^i + C^i{}_{jk} \, \delta y^k + \dot A^i{}_{jk} \, dx^k$.
		\item {\rm Berwald connection}: $\omega_j{}^i + \dot A^i{}_{jk} \, dx^k$.
	\end{enumerate}

Let $\operatorname{\boldsymbol{x}} : U \to \mathbb{R}^n$ be a local coordinate system on an open subset $U$ of $M$. 
	The {\rm Riemannian metric $\left< \cdot, \cdot \right>^{\operatorname{\boldsymbol{x}}}$ on $U$ induced by $\operatorname{\boldsymbol{x}}$} is the $\operatorname{\boldsymbol{x}}-$pull-back of the canonical Euclidean metric of $\operatorname{\boldsymbol{x}}(U)$ on $U$, that is,
	\begin{align*}
		\left< y , z \right>^{\operatorname{\boldsymbol{x}}}_x = \left< d\operatorname{\boldsymbol{x}}_x(y), d\operatorname{\boldsymbol{x}}_x(z)\right>,
	\end{align*}
	for every $x \in U$ and $y,z \in T_xM$.

\label{lema F em TU}
	Let $F:TM \to [0, \infty)$ be a strongly convex $C^0$-Finsler structure, $U$ be an open subset satisfying \eqref{definindo U} and  $(\operatorname{\boldsymbol{x}}, \operatorname{\boldsymbol{y}}) = ((x^i),(y^i))$ be a coordinate system on $TU$ as defined in \eqref{sistema de coordenadas x,y}. Let $v\in {\mathbb R^n}$ be a nonzero vector and consider
	\begin{align*} 

		\varepsilon \in \left(0,\frac{r_u \Vert v \Vert}{4nr_U}\right],
	\end{align*}
	where $r_U$ and $r_u$ are defined by \eqref{constante r_U} and \eqref{constante rho_U}, respectively. Then
	\begin{align} \label{Desigualdade para F^2}
		F^2\left(x,w+t\frac{v}{\Vert v \Vert}\right) - F^2(x,w) > \frac{r_u^2}{32}t 
	\end{align}
	for every $x \in U,$ $w \in B_{\Vert \cdot \Vert}[x, v,\varepsilon]$ and $t>0$.

The proof of Inequality \eqref{Desigualdade para F^2} follows from the difference-of-squares identity and the inequality
	\begin{align*} 
		F\left(x,w+t\frac{v}{\Vert v \Vert}\right) - F(x,w) > \frac{r_u}{8}t, 
	\end{align*}
	for every $x \in U,$ $w \in B_{\Vert \cdot \Vert}[x, v,\varepsilon]$ and $t>0$, contained in Lemma 5 of \cite{Fukuoka-Setti} (cf. Lemma 2.22 of \cite{Fukuoka-Setti2}).

\label{lema propriedade de F_epsilon} 
	$(\eta_\varepsilon \ast_v F^2)$ has the following properties for every $\varepsilon \in \left(0, \tau\right):$
	\begin{enumerate}
		\item $\operatorname{Hess}_y[(\eta_\varepsilon \ast_v F^2)(x,y)](v, v) \geq \gamma_x \Vert v \Vert^2$ for every $(x, y) \in TU$ and $v \in \mathbb{R}^n.$
		\item The {\rm radial derivative} of $\left(\eta_\varepsilon \ast_v F^2\right)$ on $\mathcal A$ satisfies
		\begin{align*}
			\frac{y^i}{\Vert y\Vert}\left(\eta_\varepsilon \ast_v F^2\right)_{y^i}(x, y) > \frac{r_u^2}{32},\,\, \forall \, (x, y) \in \mathcal A.
		\end{align*}
		\item $\left(\eta_\varepsilon \ast_v F^2\right)(x, y)<r_U^2$ for every $(x, y) \in TU$ with $\Vert y \Vert \leq \frac{1}{2}.$
		\item $\left(\eta_\varepsilon \ast_v F^2\right)(x, y)>r_U^2$ for every $(x, y) \in TU$ with $\Vert y \Vert \geq \frac{2r_U}{r_u}.$
	\end{enumerate}
	In particular, we have that $\left\{ \eta_\varepsilon \ast_v F^2 = r_U^2\right\}\cap T_xU$ is a smooth hypersurface in $T_xU$ such that its radial projection onto  $S_{\|\cdot\|}[x,0,1]$ is a diffeomorphism.

\
	\begin{enumerate}
		\item It follows directly from Theorem \ref{Equivalencias - Fortemente convexa (Definicao Classica)} and Lemma \ref{Suavização de função fortemente convexa}.
		\item Consider $(x, y) \in \mathcal{A}.$ Then
		\begin{align*}
			& \left(\eta_\varepsilon \ast_v F^2\right) \left(x, y+t\frac{y}{\|y\|}\right)-\left(\eta_\varepsilon \ast_v F^2\right) (x, y) \\
			= & \int_{B_{\|\cdot\|}[x,0,\varepsilon]} \eta_\varepsilon(z)\left[ F^2\left(x, y+t\frac{y}{\|y\|}-z\right) - F^2(x, y-z) \right]  dz \\
			= & \int_{B_{\|\cdot\|}[x,y,\varepsilon]} \eta_\varepsilon(y-z)\left[ F^2\left(x, z+t\frac{y}{\|y\|}\right) - F^2(x, z) \right] dz \\
			> &  \frac{r_u^2}{32}t,
		\end{align*}
		for $t\in (0,1)$, where the inequality is due to Lemma \ref{lema F em TU}. Thus, $\frac{r_u^2}{32}$  is a lower bound for $\frac{y^i}{\Vert y \Vert}(\eta_\varepsilon \ast_v F^2)_{y^i}(y)$.  
		\item Consider $(x, y) \in TU$ with $\Vert y \Vert \leq \frac{1}{2}.$ We have
		\begin{align*}
			\left(\eta_\varepsilon \ast_v F^2\right)(x, y) = \int \eta_\varepsilon(z)F^2\left(x, y-z\right) \, dz,
		\end{align*}
		with $z \in {B_{\|\cdot\|}[x,0,\varepsilon]}.$ Then $\Vert y-z \Vert < 1,$ what implies that $F^2(x, y-z) < r_U^2$, and therefore  $\left(\eta_\varepsilon \ast_v F^2\right)(x, y) < r_U^2.$
		\item Consider $(x, y) \in TU$ with $\Vert y \Vert \geq \frac{2r_U}{r_u}.$ We have that $\Vert y-z \Vert > 1$ for $z \in {B_{\|\cdot\|}[x,0,\varepsilon]},$ what implies $F^2\left(x, y-z\right) >  r_U^2.$ Therefore  $\left(\eta_\varepsilon \ast_v F^2\right)(x, y) > r_U^2.$
	\end{enumerate}

\label{propriedades da aplicacao F_epsilon^til}  
	The function $\tilde{F}_\varepsilon$ defined in \eqref{aplicacao F_epsilon til} satisfies the following properties for every $\varepsilon \in \left(0,\tau\right):$
	\begin{enumerate}
		\item $\tilde{F}_\varepsilon$ is a $C^0$-Finsler structure.
		\item $\tilde{F}_\varepsilon(x,\cdot)$ is smooth in $T_xU \setminus \{0\}.$



	\end{enumerate}

\label{propriedades da aplicacao F epsilon definida em TM} 
	The function $F_\varepsilon: TM \rightarrow \mathbb [0, \infty)$ defined by \eqref{F epsilon definida em TM} satisfies the following properties for every $\varepsilon \in (0, 1)$:
	\begin{enumerate}
		\item $ {F}_{\varepsilon }$ is a Finsler structure of $M$ for every $\varepsilon \in (0,1).$
		\item $ {F}_{\varepsilon } \rightarrow F$ uniformly on compact subsets of $TM$ as $\varepsilon$ converges to zero.
	\end{enumerate}

\label{definition_uniform_convergence}
	Let $M$ be a smooth manifold and $K_{TM\backslash 0}$ be a compact subset of $TM\backslash 0$.
	We say that a one-parameter family of continuous sections $E_\varepsilon$ converges uniformly to a continuous section $E$ on $K_{TM\backslash 0}$ if there exist a $C^0$-Finsler structure $F_{\pi}$ on $\pi^\ast TM$ such that for every $\delta > 0$, there exist a $\beta > 0$ such that 
	\begin{align*}
		F_\pi (x,y,E_\varepsilon(x,y) - E(x,y)) < \delta
	\end{align*}
	for every $(x,y) \in K_{TM\backslash 0}$ and every $\varepsilon \in (0,\beta)$.

\label{curvatura flag converge uniforme}
	Let $(M,F)$ be a Finsler manifold and let $F_\varepsilon$ be a mollifier smoothing of $F$.
	Let $K_M$ be a compact subset of $M$ and $\delta >0$.
	Then there exist $\beta > 0$ such that
	\begin{align*}

		\sup_{x \in K_M} \sup_{(y,z) \in \mathcal F_x} \vert K(x,y,z) - K_\varepsilon(x,y,z) \vert < \delta
	\end{align*}
	for every $\varepsilon \in (0, \beta)$.

\rm Consider the Euclidean ball $M=B_{\Vert \cdot \Vert}(0,\frac{1}{2})$ in $\mathbb{R}^2$ endowed with the following radially symmetric $C^0$-Finsler structure $F$:
	\begin{align*}
		F^2(x^1,x^2,y^1,y^2)=\max\left\{(y^1)^2 + (y^2)^2 ,\frac{(y^1)^2}{1-\Vert x\Vert^2} + \Vert x\Vert^2 (y^2)^2 \right\}.
	\end{align*}
	Set $r=\Vert x\Vert$. 
	Direct calculations implies that
	\begin{align*}
		F^2(x^1,x^2,y^1,y^2) = 
		\left\{
		\begin{array}{ccc}
			(y^1)^2 + (y^2)^2 & \text{ if }& \vert y^2 \vert \geq \frac{r}{1-r^2}\vert y^1\vert\\
			\frac{(y^1)^2}{1-\Vert x\Vert^2} + \Vert x\Vert^2 (y^2)^2 & \text{ if }& \vert y^2 \vert \leq \frac{r}{1-r^2}\vert y^1\vert.
		\end{array}
		\right.
	\end{align*} 

	Denote by $\left< \cdot, \cdot \right>_r$ the inner product corresponding to the second part of the definition of $F^2$ and denote its norm by $\Vert \cdot \Vert_r$. 
	For a fixed $r>0$, it is not difficult to choose $w,z$ in the region where $F = \Vert \cdot \Vert_r$,  such that $w$ is proportional to $(1,0)$ and $z-w$ is proportional to $(0,1)$. 
	In this case, direct calculations give
	\begin{align}
		\label{align_equacao1_nao_lusc}
		F^2(x, z) & = \Vert z \Vert^2_r = \Vert w \Vert^2_r + 2 \left< w , z-w \right>_r + \Vert z-w \Vert^2_r \nonumber \\
		& = F^2(x,w) + r^2 \Vert z-w \Vert^2, 
	\end{align}
	where the last equality holds because $w \perp z-w$, the fact that $z-w$ is proportional to $(0,1)$ and the definition of $\Vert \cdot \Vert_r$. 
	Now notice that for a fixed $r>0$, $F^2\vert_{T_xM}$ is smooth at $w$ and its differential with respect to the variable $y$ is given by 
	\begin{align*}
		d_y(F^2)_w = \frac{2w^1}{1-\Vert x\Vert^2}dy^1.
	\end{align*}
	Then $d_y(F^2)_w (z-w) = 0$ and \eqref{align_equacao1_nao_lusc} is given by
	\begin{align*}
		F^2(x, z)=F^2(x,w) + d_y (F^2)_w (z-w) + r^2 \Vert z-w \Vert^2
	\end{align*}
	which can be compared to the definition of strong convexity for $F\vert_{T_xM}$.
	But $r>0$ can be taken arbitrarily near zero,  
	what implies that there is no $\gamma_{(0,0)} >0$ such that $F(x, \cdot)$ is strongly convex with respect to $\sqrt{\frac{\gamma_{(0,0)}}{2}} \Vert \cdot \Vert$ for every $x$ in neighborhood of $(0,0)\in M$.

Let $K_{TG}$ be a compact subset of $TG.$ Given $\mu>0$ we must find $\tilde{\tau} \in (0, \tau]$ such that
	\begin{align*}
		|F_\varepsilon(x,y) - F(x,y)|  < \mu,
	\end{align*}
	for every $(x,y) \in K_{TG}$ whenever $\varepsilon \in (0, \tilde{\tau}).$

	Since $K_{TG} \subset TG$  is compact, then $K_{\mathfrak{g}} = \pi_2(\varphi^{-1}(K_{TG}))$ is a compact subset of $\mathfrak{g}\cong  \mathbb{R}^n,$ where $\pi_2:G\times \mathfrak{g} \rightarrow \mathfrak{g}$ is given by $\pi_2(x,y)=y.$

	Note that
	\begin{align*}
		F(x,y) = F_e((dL_{x^{-1}})_x (y)) = F_e(\pi_2(\varphi^{-1}(x,y)))
	\end{align*}
	and
	\begin{align*}
		F_\varepsilon(x,y) = (\tilde{F}_\varepsilon)_e((dL_{x^{-1}})_x (y)) = (\tilde{F}_\varepsilon)_e(\pi_2(\varphi^{-1}(x,y))).
	\end{align*}
	So
	\begin{align*}
		|F_\varepsilon(x,y) - F(x,y)|  = \left|(\tilde{F}_\varepsilon)_e(\pi_2(\varphi^{-1}(x,y))) - F_e(\pi_2(\varphi^{-1}(x,y)))\right|.
	\end{align*}

	By Corollary \ref{F_epsilon^til converge uniforme}, for each $\mu>0,$ there exists $\tilde{\tau}\in (0, \tau]$ such that 
	\begin{align*}
		\left|(\tilde{F}_\varepsilon)_e(z) - F_e(z)\right|  < \mu,
	\end{align*}
	for every $z \in K_{\mathfrak{g}}$ whenever $\varepsilon \in (0, \tilde{\tau})$, in particular for $z=\pi_2(\varphi^{-1}(x,y)).$ This proves that $F_\varepsilon$ converges uniformly to $F$ on $K_{TG}$ as $\varepsilon$ converges to zero.

\label{theorem_geometric_objects}
	The components of the following elements of the Finsler geometry of $(G,F)$ can be written as a quotient of sums of products of
	\begin{itemize} 
		\item $F_e(y^i \, v_i{}^a \, e_a)$;
		\item $d^m(F_e{}^2)_\mathfrak{y}(e_{a_1}, \ldots, e_{a_m}), \ a_1, \ldots, a_m \in \{1, \ldots, n\}$ and $\mathfrak{y} = y^i \, v_i{}^a \, e_a$;
		\item $y^i$, $i=1,\ldots, n$; 
		\item $v_j^{\ a}(x)$, $a,j=1, \ldots, n$;
		\item partial derivatives of any order of $v_j^{\ a}(x)$ with respect to variables $x^l$, $l=1,\ldots, n$.
	\end{itemize}
	\begin{enumerate}
		\item Fundamental tensor: $g_{ij}$.
		\item Inverse tensor: $g^{ij}$.
		\item  Cartan tensor: $A_{ijk}$. 
		\item  Cartan tensor (without normalization): $C_{ijk} = \frac{1}{F} \, A_{ijk}$. 
		\item Formal Christoffel symbols: $\gamma^{i}{}_{jk}.$
		\item Nonlinear connection: $N^i{}_j.$
		\item Chern connection: $\Gamma^i{}_{jk}.$
		\item Horizontal covariant derivative of the Cartan tensor $A$ along the distinguished (horizontal) direction $\hat{\ell} := \ell^i\frac{\delta}{\delta x^i}$: $\dot{A}.$
		\item The following connection forms:
		\begin{itemize}
			\item Cartan connection: 
			\begin{align*}
				\Gamma^i{}_{jk} \, dx^k + C^i_{jk} \, \delta y^k.
			\end{align*}
			\item Hashiguchi connection: 
			\begin{align*}
				\left( \Gamma^i{}_{jk} + \dot{A}^i{}_{jk} \right) dx^k + C^i{}_{jk} \, \delta y^k.
			\end{align*}
			\item Berwald connection:
			\begin{align*}
				\left( \Gamma^i{}_{jk} + \dot{A}^i_{jk} \right) dx^k.
			\end{align*}
		\end{itemize}
		\item $hh$-curvature tensor: $R_j{}^i{}_{kl}.$
	\end{enumerate}
	\item Moreover if we fix $x \in G$ and two transverse vectors $y,z\in T_xG$, the flag curvature $K(y,z)$, depends only on the quotient of sums of products of the aforementioned five items and $z^i$, $i=1,\ldots, n$.

\label{proposition_vertical_convergence}
	Let $(G,F)$ be a Lie group endowed with a left-invariant Finsler structure. Let $K_{\mathfrak{g}\setminus\{0\}}$ be a compact subset of $\{e\}\times (T_eG\setminus\{0\}) \cong \mathfrak{g}\setminus\{0\}$ and $\alpha = (\alpha_1,\ldots, \alpha_n)$ be a multi-index. Then,
	\begin{align*}
		D^\alpha \left( (\tilde{F}_\varepsilon)_e{}^2 \right) = \frac{\partial^{|\alpha|} (\tilde{F}_\varepsilon)_e{}^2}{\partial(y^1)^{\alpha_{1}} \cdots \partial(y^n)^{\alpha_{n}}}
	\end{align*}
	converges uniformly to
	\begin{align*}
		D^\alpha (F_e{}^2) = \frac{\partial^{|\alpha|} F_e{}^2}{\partial(y^1)^{\alpha_{1}} \cdots \partial(y^n)^{\alpha_{n}}}
	\end{align*}
	on $K_{\mathfrak{g}\setminus\{0\}}$.

\label{curvatura flag converge uniforme grupos de Lie}
	Let $(G,F)$ be a Lie group with a left-invariant Finsler structure and $F_\varepsilon$ be a left-invariant mollifier smoothing of $F$.  
	Let $K_G$ be a compact subset of $G$ and $\delta >0$.
	Then there exist $\beta > 0$ such that
	\begin{align*}

		\sup_{x \in K_G} \sup_{(y,z) \in \mathcal F_x} \vert K(x,y,z) - K_\varepsilon(x,y,z) \vert < \delta
	\end{align*}
	for every $\varepsilon \in (0, \beta)$.
